bounded_host_request.command:
set -euo pipefail
n=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$n" 2>/dev/null)" = true || exit 61
docker exec -i "$n" node --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
const env=process.env;
const wizard=readFileSync('./src/telegram/stickerWizard.mjs','utf8');
const shop=readFileSync('./src/stickers/shopHttp.mjs','utf8');
console.log('STK_LIVE_MENU_RECOVERY_PATCH='+String(wizard.includes('前回の素材登録が確認待ち')&&wizard.includes('const topicStickerStart=')));
console.log('STK_LIVE_SHOP_HTTP_MODULE='+String(shop.includes('createStickerShopHandler')));
console.log('STK_LIVE_PUBLIC_APP_URL_CONFIGURED='+String(Boolean(env.VIDEOBOT_SHOP_PUBLIC_URL)));
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,database:env.VIDEOBOT_DB_NAME,password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:4000});
try{
 const r=await pool.query("SELECT COUNT(*)::int AS n FROM information_schema.columns WHERE table_name='videobot_sticker_orders' AND column_name='invoice_url'");
 console.log('STK_SHOP_MIGRATION_016_APPLIED='+String(r.rows[0]?.n===1));
 const p=await pool.query("SELECT state->>'screen' AS screen,state->'stickerPending'->>'status' AS pending FROM videobot_creator_sessions WHERE owner_user_id=(SELECT seller_user_id FROM videobot_sticker_products WHERE product_id='sp_76f23430d1c29ca355960a95')");
 console.log('STK_SELLER_CURRENT_SCREEN='+String(p.rows[0]?.screen??'NONE'));
 console.log('STK_SELLER_PENDING_STATUS='+String(p.rows[0]?.pending??'NONE'));
}finally{await pool.end()}
NODE
echo STK_LIVE_IMAGE_MATCHES_SHOP_CCA294="$(test "$(docker inspect -f '{{.Image}}' "$n")" = "$(docker image inspect create-videobot:shop-cca294 -f '{{.Id}}' 2>/dev/null)" && echo YES || echo NO)"
echo STK_READ_ONLY_VERSION_DIAG=PASS
